    h, w = len(g), len(g[0])

    # A horizontal bar has a one-cell gap between equal nonzero colors.
    gaps = {}
    for r in range(h):
        for c in range(1, w - 1):
            color = g[r][c - 1]
            if color != 0 and g[r][c] == 0 and g[r][c + 1] == color:
                gaps.setdefault(c, []).append((r, color))

