    for c, bars in gaps.items():
        last_bar = max(r for r, _ in bars)
        if not any(g[r][c] != 0 for r in range(last_bar + 1, h)):
            continue
        bars.sort()
        for i, (r, color) in enumerate(bars):
            start = 0 if i == 0 else bars[i - 1][0] + 1
            for rr in range(start, r + 1):
                g[rr][c] = color
    return g
